            queue.add(i);
        }
    }

    while (n > 2) {
        int size = queue.size();
        n -= size;
        for (int i = 0; i < size; i++) {
            int node = queue.poll();
            int neighbor = graph.get(node).remove(0);
            if (graph.get(neighbor).size() == 1) {
                queue.add(neighbor);
            }
        }
    }

    while (!queue.isEmpty()) {
        result.add(queue.poll());
    }

    return result;
