    while(!queue.isEmpty()) {
        int[] cell = queue.poll();
        if(cell[0] == destination[0] && cell[1] == destination[1]) {
            return visited[cell[0]][cell[1]] - 1;
        }

        for(int[] dir : directions) {
            int r = cell[0] + dir[0];
            int c = cell[1] + dir[1];
