    int[] indegree = new int[n];
    for (int[] edge : edges) {
        ++indegree[edge[0]];
        ++indegree[edge[1]];
    }

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i < n; ++i) {
        if (indegree[i] == 1) {
            queue.offer(i);
        }
    }

    int day = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        while (size-- > 0) {
            int node = queue.poll();
            for (int neighbor : graph[node]) {
                --indegree[neighbor];
                if (indegree[neighbor] == 1) {
