    int left = 0, right = nums.size() - 1;

    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] > nums[right]) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return nums[left];
}

int findMax(vector<int>& nums) {
    int left = 0, right = nums.size() - 1;

    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] < nums[right]) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return nums[left];
}

int findMinAndMax(vector<int>& nums) {
    int minVal = findMin(nums);
    int maxVal = findMax(nums);
    return minVal * maxVal;
}

int main() {
    vector<int> nums = {1, 3, 5};
    cout << findMinAndMax(nums) << endl; // Output: 15
    return 0;
}

