        for (char c : word)
            inDegree[c] = 0;

    for (int i = 0; i < words.size() - 1; i++) {
        std::string word1 = words[i], word2 = words[i + 1];

        bool found = false;
        for (int j = 0; j < std::min(word1.size(), word2.size()); j++) {
            char c1 = word1[j], c2 = word2[j];
            if (c1 != c2) {
                if (!graph[c1].count(c2)) {
                    graph[c1].insert(c2);
                    inDegree[c2]++;
