        }

        if (!found && word1.size() > word2.size())
            return "";
    }

    std::queue<char> q;
    for (auto &[c, deg] : inDegree)
        if (deg == 0)
            q.push(c);

    std::string result;
    while (!q.empty()) {
        char c = q.front();
