    int n = matrix.size();
    std::priority_queue<std::pair<int, std::pair<int, int>>, std::vector<std::pair<int, std::pair<int, int>>>, std::greater<>> min_heap;

    // Initialize the min heap with the first element of each row
    for (int i = 0; i < n; ++i) {
